-- Factory ERP — foundation: platform, identity, audit, system infrastructure.
-- Conventions (docs/ARCHITECTURE.md §D): UUIDv7 keys generated by the application,
-- timestamptz for events, date for business dates (IST), text + CHECK instead of enums.

create extension if not exists pg_trgm;
create extension if not exists btree_gist;

create schema if not exists system;
create schema platform;
create schema identity;
create schema audit;

-- ---------------------------------------------------------------------------
-- Shared guard functions
-- ---------------------------------------------------------------------------

-- Raised by triggers on append-only tables. SQLSTATE FO001 is mapped by the API.
create function system.forbid_mutation() returns trigger
language plpgsql as $$
begin
  raise exception '% on %.% is not allowed: table is append-only', tg_op, tg_table_schema, tg_table_name
    using errcode = 'FO001';
end;
$$;

create function system.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Platform
-- ---------------------------------------------------------------------------

-- GST state codes. Reference data — must be verified against official sources [VERIFY R-09].
create table platform.states (
  code char(2) primary key check (code ~ '^[0-9]{2}$'),
  name text not null
);

