create table platform.companies (
  id                uuid primary key,
  legal_name        text not null check (length(legal_name) between 2 and 200),
  trade_name        text,
  gstin             text unique check (gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  state_code        char(2) not null references platform.states (code),
  pan               text,
  address_line1     text not null,
  address_line2     text,
  city              text not null,
  postal_code       text not null,
  phone             text,
  email             text,
  bank_details      jsonb,
  invoice_terms     text,
  invoice_prefix    text not null default 'INV' check (invoice_prefix ~ '^[A-Z0-9-]{1,6}$'),
  -- [CA validation point] grand-total rounding policy used by the GST engine.
  invoice_rounding  text not null default 'NEAREST_RUPEE' check (invoice_rounding in ('NEAREST_RUPEE', 'NONE')),
  -- Round 2 §7.3: until PRODUCTION, generated documents carry a SPECIMEN watermark.
  finance_readiness text not null default 'DEVELOPMENT'
    check (finance_readiness in ('DEVELOPMENT', 'CA_REVIEW', 'PARALLEL_RUN', 'PRODUCTION')),
  is_demo           boolean not null default false,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (gstin is null or substr(gstin, 1, 2) = state_code)
);

create trigger companies_touch before update on platform.companies
  for each row execute function system.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Identity & access
-- ---------------------------------------------------------------------------

create table identity.users (
  id            uuid primary key,
  username      text not null unique check (username ~ '^[a-z0-9._-]{3,64}$'),
  display_name  text not null check (length(display_name) between 1 and 100),
  password_hash text not null,
  status        text not null default 'ACTIVE' check (status in ('ACTIVE', 'DISABLED')),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create trigger users_touch before update on identity.users
  for each row execute function system.touch_updated_at();

create table identity.roles (
  code        text primary key check (code ~ '^[A-Z_]{2,40}$'),
  name        text not null,
  description text not null
);

-- Permission codes are defined in code (packages/contracts/src/permissions.ts); roles are
-- data. A test asserts every stored code exists in the code registry.
create table identity.role_permissions (
  role_code  text not null references identity.roles (code) on delete cascade,
  permission text not null check (permission ~ '^[a-z_]+(\.[a-z_]+)+$'),
  primary key (role_code, permission)
);

create table identity.user_roles (
  user_id    uuid not null references identity.users (id) on delete cascade,
  role_code  text not null references identity.roles (code),
  company_id uuid not null references platform.companies (id),
  primary key (user_id, role_code, company_id)
);

create table identity.sessions (
  id           uuid primary key,
  user_id      uuid not null references identity.users (id) on delete cascade,
  company_id   uuid not null references platform.companies (id),
  token_hash   bytea not null unique,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  last_seen_at timestamptz not null default now(),
  revoked_at   timestamptz,
  ip           text,
  user_agent   text
);

create index sessions_user_idx on identity.sessions (user_id) where revoked_at is null;

-- ---------------------------------------------------------------------------
-- Audit (append-only; written in the same transaction as the change it records)
-- ---------------------------------------------------------------------------

create table audit.events (
  id            uuid primary key,
  occurred_at   timestamptz not null default now(),
  company_id    uuid references platform.companies (id),
  actor_user_id uuid references identity.users (id),
  actor_kind    text not null check (actor_kind in ('user', 'ai_agent', 'system', 'integration')),
  ai_session_id uuid,
  request_id    text not null,
  command       text not null,
  entity_type   text not null,
  entity_id     uuid not null,
  before        jsonb,
  after         jsonb,
  metadata      jsonb
);

create index audit_events_entity_idx on audit.events (entity_type, entity_id, occurred_at);
create index audit_events_time_idx on audit.events (occurred_at desc);

create trigger audit_events_append_only before update or delete on audit.events
  for each row execute function system.forbid_mutation();
create trigger audit_events_no_truncate before truncate on audit.events
  for each statement execute function system.forbid_mutation();

-- ---------------------------------------------------------------------------
-- System infrastructure
-- ---------------------------------------------------------------------------

-- Idempotency: one row per (user, key). The stored response is replayed for retries.
create table system.idempotency_keys (
  user_id      uuid not null references identity.users (id) on delete cascade,
  key          text not null check (length(key) between 8 and 200),
  command      text not null,
  request_hash text not null,
  response     jsonb,
  created_at   timestamptz not null default now(),
  primary key (user_id, key)
);

-- Transactional outbox: side effects (PDFs, notifications, sync) are recorded in the same
-- transaction as the business change and processed asynchronously by the worker.
create table system.outbox_events (
  id             uuid primary key,
  occurred_at    timestamptz not null default now(),
  topic          text not null,
  aggregate_type text not null,
  aggregate_id   uuid not null,
  payload        jsonb not null,
  status         text not null default 'PENDING' check (status in ('PENDING', 'DONE', 'FAILED')),
  attempts       integer not null default 0 check (attempts >= 0),
  available_at   timestamptz not null default now(),
  last_error     text,
  processed_at   timestamptz
);

create index outbox_pending_idx on system.outbox_events (available_at) where status = 'PENDING';

-- Gapless document numbering. One row per company × doc type × series × fiscal year,
-- locked FOR UPDATE inside the issuing transaction.
create table system.number_series (
  id                 uuid primary key,
  company_id         uuid not null references platform.companies (id),
  doc_type           text not null,
  series_code        text not null default 'DEFAULT',
  fiscal_year        text not null check (fiscal_year ~ '^[0-9]{4}-[0-9]{2}$'),
  prefix             text not null,
  pad_width          integer not null default 5 check (pad_width between 1 and 10),
  -- [VERIFY R-02] maximum document-number length is regulatory data, not a constant.
  max_length         integer not null default 16 check (max_length between 4 and 40),
  next_value         bigint not null default 1 check (next_value >= 1),
  last_document_date date,
  unique (company_id, doc_type, series_code, fiscal_year)
);
